package com.bplus.share;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Inbound share data is displayed and staged only. User chooses destination and presses Send. */
public final class ReceiveShareActivity extends Activity{
 private LinearLayout box;private TextView status;private final ArrayList<JSONObject> files=new ArrayList<>();private final ArrayList<File> staged=new ArrayList<>();private String text="";private boolean committed;private volatile boolean cancelled;
 protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.incoming_share),true,null));ScrollView scroll=new ScrollView(this);box=Ui.col(this);Ui.pad(box,20,16,20,16,this);scroll.addView(box);root.addView(scroll,Ui.lpW1());status=Ui.t(this,getString(R.string.share_loading),15,Ui.text,App.cairoSB);box.addView(status);setContentView(root);Intent incoming=getIntent();if(!Intent.ACTION_SEND.equals(incoming.getAction())&&!Intent.ACTION_SEND_MULTIPLE.equals(incoming.getAction())){finish();return;}new Thread(()->load(incoming)).start();}
 @SuppressWarnings("deprecation") private void load(Intent i){try{CharSequence body=i.getCharSequenceExtra(Intent.EXTRA_TEXT);text=body==null?"":body.toString();if(!ImportRules.text(text))throw new IOException(getString(R.string.share_text_limit));LinkedHashSet<Uri> uris=new LinkedHashSet<>();if(Intent.ACTION_SEND_MULTIPLE.equals(i.getAction())){ArrayList<Uri> list=i.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(list!=null)uris.addAll(list);}else{Uri uri=i.getParcelableExtra(Intent.EXTRA_STREAM);if(uri!=null)uris.add(uri);}if(i.getClipData()!=null)for(int n=0;n<i.getClipData().getItemCount();n++){Uri u=i.getClipData().getItemAt(n).getUri();if(u!=null)uris.add(u);}if(!ImportRules.count(uris.size()))throw new IOException(getString(R.string.share_file_limit));long total=0;File dir=new File(getFilesDir(),"shared");if(!dir.exists()&&!dir.mkdirs())throw new IOException();for(Uri uri:uris){if(cancelled)return;if(!ImportRules.source(uri.getScheme(),uri.getAuthority(),getPackageName()))throw new IOException(getString(R.string.share_uri_refused));String name="shared-file";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}if(name==null)name="shared-file";name=new File(name.replace('\\','/')).getName();if(name.isEmpty())name="shared-file";File local=new File(dir,UUID.randomUUID()+"-"+name);synchronized(staged){staged.add(local);}long size=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(local)){if(in==null)throw new IOException();byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0){if(cancelled)throw new IOException();size+=n;total+=n;if(!ImportRules.bytes(size,total))throw new IOException(getString(R.string.share_size_limit));out.write(buffer,0,n);}}Uri saved=Uri.parse("content://"+getPackageName()+".files/shared/"+Uri.encode(local.getName()));files.add(new JSONObject().put("uri",saved.toString()).put("name",name).put("size",size));}if(text.isEmpty()&&files.isEmpty())throw new IOException(getString(R.string.share_empty));runOnUiThread(this::choose);}catch(Exception e){cleanup();runOnUiThread(()->{if(!isFinishing()){status.setText(getString(R.string.share_import_failed)+"\n"+(e.getMessage()==null?"":e.getMessage()));}});}finally{if(cancelled)cleanup();}}
 private void choose(){if(cancelled||isFinishing()){cleanup();return;}StringBuilder preview=new StringBuilder(getString(R.string.share_preview,files.size()));for(JSONObject f:files)preview.append("\n").append(f.optString("name")).append(" · ").append(Ui.fmtSize(f.optLong("size")));if(!text.isEmpty())preview.append("\n\n").append(text);status.setText(preview.toString());JSONArray peers=Store.peers();if(peers.length()==0){box.addView(Ui.t(this,getString(R.string.no_chats),14,Ui.dim,App.cairoSB));return;}TextView label=Ui.t(this,getString(R.string.share_choose_chat),15,Ui.text,App.cairoB);box.addView(label);for(int n=0;n<peers.length();n++){JSONObject peer=peers.optJSONObject(n);if(peer==null)continue;TextView target=Ui.ghost(this,peer.optString("name"));Ui.pad(target,12,12,12,12,this);box.addView(target);target.setOnClickListener(v->new AppDialog(this).setTitle(R.string.incoming_share).setMessage(getString(R.string.share_target_confirm,peer.optString("name"),files.size(),text.isEmpty()?0:1)).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.send_now,(d,k)->send(peer)).show());}}
 private void send(JSONObject peer){if(committed||cancelled)return;committed=true;box.removeAllViews();box.addView(status);status.setText(R.string.sending);new Thread(()->{int ok=0,count=files.size()+(text.isEmpty()?0:1);if(!text.isEmpty()&&TransferService.sendTextToPeer(peer,text))ok++;for(JSONObject m:files)if(TransferService.sendToPeer(peer,Uri.parse(m.optString("uri")),m.optString("name"),m.optLong("size")))ok++;final int sent=ok;runOnUiThread(()->{status.setText(getString(R.string.send_items_result,sent,count));TextView open=Ui.cta(this,getString(R.string.share_open_chat));box.addView(open);open.setOnClickListener(v->{startActivity(new Intent(this,ChatActivity.class).putExtra("peer",peer.optString("id")));finish();});});}).start();}
 private void cleanup(){if(committed)return;synchronized(staged){for(File f:staged)f.delete();}}
 protected void onDestroy(){cancelled=true;cleanup();super.onDestroy();}
}
